    civic_address:'street address',intersection:'intersection',landmark:'landmark',named_place:'named place',area:'area',caller:'caller words',prior_confirmation:'earlier confirmation',transcript:'call transcript',reported_label:'reported location field',uncertain:'uncertain address wording',approximate:'approximate or nearby',reported:'secondhand, not independently verified',negated:'negated location',historical:'past location',WITHIN_REPORTED_ACCURACY:'known accuracy circle inside the area (local approximation)',
